static bool resolve_path(const char* rel, char* out_buf, size_t cap) {
    if (rel == nullptr || out_buf == nullptr || cap == 0) {
        return false;
    }
    if (access(rel, F_OK) == 0) {
        if (realpath(rel, out_buf) != nullptr) return true;
        strncpy(out_buf, rel, cap - 1);
        return true;
    }
    const char* prefixes[] = {
        "/workspace/soc-ap/",
        "/workspace/",
        "/home/sushaohua/workspace/ai_soc_project/",
        "../",
        "../../",
        "../../../",
        "../../../../"
    };
    for (size_t i = 0; i < 7; ++i) {
        char full[512];
        snprintf(full, sizeof(full), "%s%s", prefixes[i], rel);
        if (access(full, F_OK) == 0) {
            if (realpath(full, out_buf) != nullptr) return true;
            strncpy(out_buf, full, cap - 1);
            return true;
        }
    }
    return false;
}

/**
 * @brief 拉起独立测试 dbus-daemon 并获取会话总线连接地址
 */
static pid_t spawn_dbus_daemon(char* out_addr, size_t addr_len) {
    char conf[512] = {0};
    char bin[512] = {0};
    char lib[512] = {0};

    bool ok_conf = resolve_path("soc-ap/config/dbus/twin/session_twin.conf", conf, sizeof(conf)) ||
                   resolve_path("config/dbus/twin/session_twin.conf", conf, sizeof(conf));
    bool ok_bin = resolve_path("soc-ap/third_party/install/bin/dbus-daemon", bin, sizeof(bin)) ||
                  resolve_path("/usr/local/bin/dbus-daemon", bin, sizeof(bin)) ||
                  resolve_path("/usr/bin/dbus-daemon", bin, sizeof(bin));
    bool ok_lib = resolve_path("soc-ap/third_party/install/lib", lib, sizeof(lib)) ||
                  resolve_path("/usr/local/lib", lib, sizeof(lib));

    if (!ok_conf || !ok_bin) {
        return -1;
    }

    int pfd[2];
    if (pipe(pfd) != 0) {
        return -1;
    }

    pid_t pid = fork();
    if (pid == 0) {
        if (ok_lib) {
            setenv("LD_LIBRARY_PATH", lib, 1);
        }
        close(pfd[0]);
        dup2(pfd[1], STDOUT_FILENO);
        close(pfd[1]);
        execl(bin, bin, "--config-file", conf, "--print-address", "--nofork", (char*)nullptr);
        _exit(127);
    }

    close(pfd[1]);
    char buf[256] = {0};
    ssize_t n = read(pfd[0], buf, sizeof(buf) - 1);
    close(pfd[0]);
    if (n <= 0) {
        kill(pid, SIGTERM);
        return -1;
    }
    char* nl = strchr(buf, '\n');
    if (nl != nullptr) {
        *nl = '\0';
    }
    strncpy(out_addr, buf, addr_len - 1);
    return pid;
}

/**
 * @brief 收到原始温度 DDS 样本时的异步打印回调
 */
static void on_raw_temp_received(const aisoc_raw_temp_t* sample, void* user_data) {
    (void)user_data;
    if (sample != nullptr) {
        const minimc_job_resp_t jr = { req_f->payload.data[0], 0U, 100U, 35U };
        std::memcpy(pl, &jr, sizeof(jr));
        return sizeof(jr);
    }
    if (cmd == MINIMC_CMD_LEVEL_GRID_QUERY || cmd == MINIMC_CMD_LEVEL_TRIGGER) {
        *out_cmd = MINIMC_CMD_LEVEL_GRID_QUERY;
        minimc_level_grid_wire_payload_t gr = { 5U, 5U, {0} };
        for (int i = 0; i < 9; ++i) gr.z_offset_um[i] = (int16_t)((i - 4) * 10);
        std::memcpy(pl, &gr, sizeof(gr));
        return sizeof(gr);
    }
    if (cmd == MINIMC_CMD_SLOT_SELECT) {
        const minimc_filament_resp_t fr = { req_f->payload.data[0], 0x0FU, 2U, 0U };
        std::memcpy(pl, &fr, sizeof(fr));
        return sizeof(fr);
    }
    if (cmd == MINIMC_CMD_GCODE_EXEC) {
        const minimc_gcode_resp_t gc = { 0U, 8U, req_f->header.seq };
        std::memcpy(pl, &gc, sizeof(gc));
        return sizeof(gc);
    }
    if (cmd == MINIMC_CMD_OTA_STATUS) {
        const minimc_payload_ota_status_t st = { 2U, 0U, 512U, 512U };
        std::memcpy(pl, &st, sizeof(st));
        return sizeof(st);
    }
    *out_cmd = MINIMC_CMD_ACK;
    return 0U;
}

/**
 * @brief 向 PTY 写入指定 MiniMCProto 响应帧
 */
static void send_pty_resp(int fd, const minimc::FrameView* req_f) {
    uint8_t pl[64] = {0};
    uint8_t out_cmd = req_f->header.cmd_id;
    const size_t pl_len = fill_pty_resp_payload(req_f, &out_cmd, pl);
    minimc::FrameHeader hdr = {};
    hdr.sof_1 = MINIMC_SOF_1;
    hdr.sof_2 = MINIMC_SOF_2;
    hdr.src_id = req_f->header.dst_id;
    hdr.dst_id = MINIMC_DEV_AP;
    hdr.flags = MINIMC_RESP_FLAGS_V2;
    hdr.cmd_id = out_cmd;
    hdr.hop_limit = 10U;
    hdr.seq = req_f->header.seq;
    hdr.payload_len = (uint16_t)pl_len;
    uint8_t out_buf[128] = {0};
    minimc::Bytes p(pl, pl_len);
    minimc::MutableBytes m(out_buf, sizeof(out_buf));
    size_t enc_len = 0U;
    if (minimc::encode_frame(hdr, p, m, &enc_len) == minimc::Status::OK) {
        (void)write(fd, out_buf, enc_len);
    }
}

